values ('claude-skills', '5 סקילים ל־Claude למעצבי מוצר', 'כל פקודות ההתקנה, הקישורים ופרומפט לניסיון לכל סקיל. UI/UX Pro Max, Frontend Design, Emil Kowalski, App Store Screenshots ו־gstack.', 'DROP / 001', 'סקילים', 'ai',
  array['claude', 'claude-code', 'skills', 'design']::text[], 'free', true, 'published', now(),
  '[{"id":"seed0001","type":"text","text":"**צריך:** Claude Code מותקן. לפקודות `npx` צריך גם Node.js.\n**לפני כל התקנה:** תעבור על הקוד בריפו. סקילים ופלאגינים רצים אצלך במחשב.","variant":"note"},{"id":"seed0002","type":"heading","text":"01‏ · UI/UX Pro Max","level":2},{"id":"seed0003","type":"text","text":"**מערכת עיצוב.** מלמד את Claude כללי עיצוב: היררכיה, צבעים, טיפוגרפיה ודפוסי UX, לפני שהוא כותב קוד.","variant":"plain"},{"id":"seed0004","type":"link","url":"https://github.com/nextlevelbuilder/ui-ux-pro-max-skill","title":"UI/UX Pro Max","description":""},{"id":"seed0005","type":"code","title":"התקנה · בתוך סשן של Claude Code","language":"bash","code":"/plugin marketplace add nextlevelbuilder/ui-ux-pro-max-skill\n/plugin install ui-ux-pro-max@ui-ux-pro-max-skill"},{"id":"seed0006","type":"prompt","title":"נסה את הפרומפט","text":"תעצב דף הזמנות לצימר בגליל. תעבוד לפי כללי העיצוב שלך."},{"id":"seed0007","type":"heading","text":"02‏ · Frontend Design","level":2},{"id":"seed0008","type":"text","text":"**נגד עיצוב גנרי.** הסקיל הרשמי של Anthropic לממשקים. בוחר כיוון אסתטי לפני הקוד ומתרחק מלייאאוטים גנריים של AI. נכנס לפעולה לבד כשאתה מבקש מ־Claude לבנות פרונטאנד.","variant":"plain"},{"id":"seed0009","type":"link","url":"https://claude.com/plugins/frontend-design","title":"Frontend Design","description":""},{"id":"seed0010","type":"code","title":"התקנה · בתוך סשן של Claude Code. המרקטפלייס הרשמי של Anthropic נוסף אוטומטית בסשן הראשון בטרמינל.","language":"bash","code":"/plugin install frontend-design@claude-plugins-official"},{"id":"seed0011","type":"prompt","title":"נסה את הפרומפט","text":"תבנה דשבורד לסטודיו פילאטיס. שירגיש מעוצב, לא כמו תבנית."},{"id":"seed0012","type":"heading","text":"03‏ · Emil Kowalski","level":2},{"id":"seed0013","type":"text","text":"**אנימציה.** 15 סקילים של Emil Kowalski, שעבד ב־Vercel וב־Linear ויצר את Sonner: בניית אנימציות, ביקורת easing ומשך, תיקון אנימציות שנתקעות ובדיקת UI עם דאטה קיצוני.","variant":"plain"},{"id":"seed0014","type":"link","url":"https://github.com/emilkowalski/skills","title":"Emil Kowalski","description":""},{"id":"seed0015","type":"code","title":"התקנה · בטרמינל. צריך Node.js.","language":"bash","code":"npx skills@latest add emilkowalski/skills"},{"id":"seed0016","type":"prompt","title":"נסה את הפרומפט","text":"תבדוק את האנימציה של המודאל ותתקן את ה־easing והמשך."},{"id":"seed0017","type":"heading","text":"04‏ · App Store Screenshots","level":2},{"id":"seed0018","type":"text","text":"**השקה.** מקים עורך Next.js שמייצר צילומי מסך שיווקיים ל־App Store ול־Google Play.","variant":"plain"},{"id":"seed0019","type":"link","url":"https://github.com/ParthJadhav/app-store-screenshots","title":"App Store Screenshots","description":""},{"id":"seed0020","type":"code","title":"התקנה · בטרמינל. צריך Node.js.","language":"bash","code":"npx skills add ParthJadhav/app-store-screenshots -a claude-code"},{"id":"seed0021","type":"prompt","title":"נסה את הפרומפט","text":"תכין צילומי מסך ל־App Store לאפליקציית הרגלים. רגוע, חם, פרימיום."},{"id":"seed0022","type":"heading","text":"05‏ · gstack","level":2},{"id":"seed0023","type":"text","text":"**ביקורת עיצוב.** ערכת הכלים של Garry Tan ל־Claude Code. `/plan-design-review` נותנת ציון 0–10 לכל ממד עיצובי בתוכנית, מסבירה איך נראה 10 ומתקנת את התוכנית. `/design-review` עושה את אותה בדיקה ומתקנת בעצמה את מה שמצאה.","variant":"plain"},{"id":"seed0024","type":"link","url":"https://github.com/garrytan/gstack","title":"gstack","description":""},{"id":"seed0025","type":"code","title":"התקנה · בטרמינל. צריך Git ו־Bun (גרסה 1.3.3 ומעלה).","language":"bash","code":"git clone --single-branch --depth 1 https://github.com/garrytan/gstack.git ~/.claude/skills/gstack && cd ~/.claude/skills/gstack && ./setup"},{"id":"seed0026","type":"prompt","title":"נסה את הפרומפט","text":"/plan-design-review\nתדרג את התוכנית 0–10 ותתקן כל מה שמתחת ל־10."},{"id":"seed0027","type":"divider"},{"id":"seed0028","type":"heading","text":"מאיפה להתחיל","level":2},{"id":"seed0029","type":"text","text":"1. **UI/UX Pro Max** בשביל הכללים\n2. **Emil Kowalski** בשביל התנועה\n3. **gstack** לביקורת לפני שמשחררים","variant":"plain"},{"id":"seed0030","type":"text","text":"סקיל לא יעצב במקומך. הוא חוסך לך להסביר ל־Claude את אותם כללים בכל פעם.","variant":"tip"},{"id":"seed0031","type":"text","text":"הפקודות נלקחו מה־README הרשמי של כל פרויקט (27.10.2026).","variant":"plain"}]'::jsonb)
